class Solution:
    def minArea(self, image: list[list[str]], x: int, y: int) -> int:
        m, n = len(image), len(image[0])
        def search_rows(lo, hi, check):
            while lo < hi:
                mid = (lo+hi)//2
                if check(mid): hi = mid
                else: lo = mid+1
            return lo
        def search_cols(lo, hi, check):
            while lo < hi:
                mid = (lo+hi)//2
                if check(mid): hi = mid
                else: lo = mid+1
            return lo
        top = search_rows(0, x, lambda r: '1' in image[r])
        bottom = search_rows(x+1, m, lambda r: '1' not in image[r])
        left = search_cols(0, y, lambda c: any(image[r][c]=='1' for r in range(m)))
        right = search_cols(y+1, n, lambda c: not any(image[r][c]=='1' for r in range(m)))
        return (bottom-top)*(right-left)

class Solution:
    def numIslands2(self, m: int, n: int, positions: list[list[int]]) -> list[int]:
        parent = {}
        self.count = 0
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                self.count -= 1
        res = []
        for r, c in positions:
            if (r,c) in parent:
                res.append(self.count)
                continue
            parent[(r,c)] = (r,c)
            self.count += 1
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if (nr,nc) in parent:
                    union((r,c),(nr,nc))
            res.append(self.count)
        return res

class Solution:
    def isAdditiveNumber(self, num: str) -> bool:
        n = len(num)
        for i in range(1, n):
            for j in range(i+1, n):
                a, b = num[:i], num[i:j]
                if (len(a) > 1 and a[0] == '0') or (len(b) > 1 and b[0] == '0'):
                    continue
                while j < n:
                    c = str(int(a) + int(b))
                    if not num[j:].startswith(c):
                        break
                    j += len(c)
                    a, b = b, c
                if j == n:
                    return True
        return False

class NumArray:
    def __init__(self, nums: list[int]):
        self.n = len(nums)
        self.nums = [0] * self.n
        self.bit = [0] * (self.n + 1)
        for i, v in enumerate(nums):
            self.update(i, v)

    def _add(self, i, delta):
        i += 1
        while i <= self.n:
            self.bit[i] += delta
            i += i & (-i)

    def _prefix(self, i):
        s = 0
        i += 1
        while i > 0:
            s += self.bit[i]
            i -= i & (-i)
        return s

    def update(self, index: int, val: int) -> None:
        delta = val - self.nums[index]
        self.nums[index] = val
        self._add(index, delta)

    def sumRange(self, left: int, right: int) -> int:
        return self._prefix(right) - (self._prefix(left-1) if left > 0 else 0)

class NumMatrix:
    def __init__(self, matrix: list[list[int]]):
        self.m, self.n = len(matrix), len(matrix[0])
        self.mat = [[0]*self.n for _ in range(self.m)]
        self.bit = [[0]*(self.n+1) for _ in range(self.m+1)]
        for i in range(self.m):
            for j in range(self.n):
                self.update(i, j, matrix[i][j])

    def _add(self, r, c, delta):
        i = r + 1
        while i <= self.m:
            j = c + 1
            while j <= self.n:
                self.bit[i][j] += delta
                j += j & (-j)
            i += i & (-i)

    def _query(self, r, c):
        s = 0
        i = r + 1
        while i > 0:
            j = c + 1
            while j > 0:
                s += self.bit[i][j]
                j -= j & (-j)
            i -= i & (-i)
        return s

    def update(self, row, col, val):
        delta = val - self.mat[row][col]
        self.mat[row][col] = val
        self._add(row, col, delta)

    def sumRegion(self, r1, c1, r2, c2):
        return self._query(r2,c2)-self._query(r1-1,c2)-self._query(r2,c1-1)+self._query(r1-1,c1-1)

class Solution:
    def findMinHeightTrees(self, n: int, edges: list[list[int]]) -> list[int]:
        if n <= 2:
            return list(range(n))
        from collections import defaultdict, deque
        adj = defaultdict(set)
        for u, v in edges:
            adj[u].add(v)
            adj[v].add(u)
        leaves = deque(i for i in range(n) if len(adj[i]) == 1)
        remaining = n
        while remaining > 2:
            remaining -= len(leaves)
            new_leaves = deque()
            for leaf in leaves:
                neighbor = adj[leaf].pop()
                adj[neighbor].remove(leaf)
                if len(adj[neighbor]) == 1:
                    new_leaves.append(neighbor)
            leaves = new_leaves
        return list(leaves)

