class Solution:
    def nthSuperUglyNumber(self, n: int, primes: list[int]) -> int:
        dp = [1] * n
        k = len(primes)
        ptrs = [0] * k
        for i in range(1, n):
            candidates = [dp[ptrs[j]] * primes[j] for j in range(k)]
            dp[i] = min(candidates)
            for j in range(k):
                if candidates[j] == dp[i]:
                    ptrs[j] += 1
        return dp[-1]

class Solution:
    def verticalOrder(self, root: TreeNode) -> list[list[int]]:
        if not root:
            return []
        from collections import defaultdict, deque
        col_map = defaultdict(list)
        q = deque([(root, 0)])
        while q:
            node, col = q.popleft()
            col_map[col].append(node.val)
            if node.left:
                q.append((node.left, col-1))
            if node.right:
                q.append((node.right, col+1))
        return [col_map[c] for c in sorted(col_map)]

class Solution:
    def removeDuplicateLetters(self, s: str) -> str:
        last = {c: i for i, c in enumerate(s)}
        stack = []
        in_stack = set()
        for i, c in enumerate(s):
            if c in in_stack:
                continue
            while stack and c < stack[-1] and last[stack[-1]] > i:
                in_stack.remove(stack.pop())
            stack.append(c)
            in_stack.add(c)
        return ''.join(stack)

class Solution:
    def shortestDistance(self, grid: list[list[int]]) -> int:
        from collections import deque
        m, n = len(grid), len(grid[0])
        dist = [[0]*n for _ in range(m)]
        reach = [[0]*n for _ in range(m)]
        buildings = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    buildings += 1
                    visited = [[False]*n for _ in range(m)]
                    q = deque([(i,j,0)])
                    visited[i][j] = True
                    while q:
                        x,y,d = q.popleft()
                        for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                            nx,ny = x+dx,y+dy
                            if 0<=nx<m and 0<=ny<n and not visited[nx][ny] and grid[nx][ny]==0:
                                visited[nx][ny] = True
                                dist[nx][ny] += d+1
                                reach[nx][ny] += 1
                                q.append((nx,ny,d+1))
        res = float('inf')
        for i in range(m):
            for j in range(n):
                if grid[i][j]==0 and reach[i][j]==buildings:
                    res = min(res, dist[i][j])
        return res if res != float('inf') else -1

class Solution:
    def maxProduct(self, words: list[str]) -> int:
        masks = [0] * len(words)
        for i, w in enumerate(words):
            for c in w:
                masks[i] |= 1 << (ord(c) - ord('a'))
        res = 0
        for i in range(len(words)):
