class SummaryRanges:
    def __init__(self):
        from sortedcontainers import SortedDict
        self.intervals = SortedDict()

    def addNum(self, value: int) -> None:
        intervals = self.intervals
        idx = intervals.bisect_left(value)
        merged_start = merged_end = value
        if idx > 0:
            prev_start = intervals.keys()[idx-1]
            prev_end = intervals[prev_start]
            if prev_end >= value:
                return
            if prev_end == value - 1:
                merged_start = prev_start
                del intervals[prev_start]
                idx -= 1
        if idx < len(intervals):
            next_start = intervals.keys()[idx]
            if next_start == value:
                return
            if next_start == value + 1:
                merged_end = intervals[next_start]
                del intervals[next_start]
        intervals[merged_start] = merged_end

    def getIntervals(self) -> list[list[int]]:
        return [[k, v] for k, v in self.intervals.items()]

class SnakeGame:
    def __init__(self, width: int, height: int, food: list[list[int]]):
        from collections import deque
        self.width = width
        self.height = height
        self.food = food
        self.food_idx = 0
        self.snake = deque([(0, 0)])
        self.body = {(0, 0)}
        self.score = 0

    def move(self, direction: str) -> int:
        head_r, head_c = self.snake[0]
        d = {'U':(-1,0),'D':(1,0),'L':(0,-1),'R':(0,1)}
        dr, dc = d[direction]
        nr, nc = head_r+dr, head_c+dc
        if nr<0 or nr>=self.height or nc<0 or nc>=self.width:
            return -1
        if self.food_idx < len(self.food) and [nr,nc] == self.food[self.food_idx]:
            self.food_idx += 1
            self.score += 1
        else:
            tail = self.snake.pop()
            self.body.remove(tail)
        if (nr, nc) in self.body:
            return -1
        self.snake.appendleft((nr, nc))
        self.body.add((nr, nc))
        return self.score

class Twitter:
    def __init__(self):
        from collections import defaultdict
        self.time = 0
        self.tweets = defaultdict(list)
        self.following = defaultdict(set)

    def postTweet(self, userId: int, tweetId: int) -> None:
        self.tweets[userId].append((self.time, tweetId))
        self.time += 1

    def getNewsFeed(self, userId: int) -> list[int]:
        import heapq
        tweets = []
        users = self.following[userId] | {userId}
        for u in users:
            tweets.extend(self.tweets[u][-10:])
        return [t for _, t in heapq.nlargest(10, tweets)]

    def follow(self, followerId: int, followeeId: int) -> None:
        self.following[followerId].add(followeeId)

    def unfollow(self, followerId: int, followeeId: int) -> None:
        self.following[followerId].discard(followeeId)

class Solution:
    def isReflected(self, points: list[list[int]]) -> bool:
        point_set = set(map(tuple, points))
        min_x = min(p[0] for p in points)
        max_x = max(p[0] for p in points)
        total = min_x + max_x
        for x, y in point_set:
            if (total - x, y) not in point_set:
                return False
        return True

