class Solution:
    def sortTransformedArray(self, nums: list[int], a: int, b: int, c: int) -> list[int]:
        def f(x):
            return a*x*x + b*x + c
        n = len(nums)
        res = [0] * n
        l, r = 0, n - 1
        idx = n-1 if a >= 0 else 0
        while l <= r:
            fl, fr = f(nums[l]), f(nums[r])
            if a >= 0:
                if fl >= fr:
                    res[idx] = fl; l += 1
                else:
                    res[idx] = fr; r -= 1
                idx -= 1
            else:
                if fl <= fr:
                    res[idx] = fl; l += 1
                else:
                    res[idx] = fr; r -= 1
                idx += 1
        return res

class Solution:
    def maxKilledEnemies(self, grid: list[list[str]]) -> int:
        if not grid:
            return 0
        m, n = len(grid), len(grid[0])
        col_hits = [0] * n
        res = 0
        for i in range(m):
            for j in range(n):
                if j == 0 or grid[i][j-1] == 'W':
                    row_hits = 0
                    for k in range(j, n):
                        if grid[i][k] == 'W': break
                        if grid[i][k] == 'E': row_hits += 1
                if i == 0 or grid[i-1][j] == 'W':
                    col_hits[j] = 0
                    for k in range(i, m):
