                    prefix += s
                    idx = sl.bisect_left(prefix - k)
                    if idx < len(sl):
                        res = max(res, prefix - sl[idx])
                    sl.add(prefix)
        return res

class Solution:
    def depthSumInverse(self, nestedList) -> int:
        unweighted = weighted = 0
        level = nestedList
        while level:
            next_level = []
            for item in level:
                if item.isInteger():
                    unweighted += item.getInteger()
                else:
                    next_level.extend(item.getList())
            weighted += unweighted
            level = next_level
        return weighted

