        res = [0] * length
        for start, end, val in updates:
            res[start] += val
            if end + 1 < length:
                res[end+1] -= val
        for i in range(1, length):
            res[i] += res[i-1]
        return res

class Solution:
    def superPow(self, a: int, b: list[int]) -> int:
        MOD = 1337
        def power(base, exp):
            result = 1
            base %= MOD
            while exp:
                if exp & 1:
                    result = result * base % MOD
                base = base * base % MOD
                exp >>= 1
            return result
        result = 1
        for digit in b:
            result = power(result, 10) * power(a, digit) % MOD
        return result

