class RandomizedCollection:
    def __init__(self):
        from collections import defaultdict
        self.vals = []
        self.idx_map = defaultdict(set)

    def insert(self, val: int) -> bool:
        self.idx_map[val].add(len(self.vals))
        self.vals.append(val)
        return len(self.idx_map[val]) == 1

    def remove(self, val: int) -> bool:
        if not self.idx_map[val]:
            return False
        idx = self.idx_map[val].pop()
        last = self.vals[-1]
        self.vals[idx] = last
        self.idx_map[last].add(idx)
        self.idx_map[last].discard(len(self.vals)-1)
        self.vals.pop()
        return True

    def getRandom(self) -> int:
        import random
        return random.choice(self.vals)

