class Solution:
    def isRectangleCover(self, rectangles: list[list[int]]) -> bool:
        area = 0
        corners = set()
        x1 = y1 = float('inf')
        x2 = y2 = float('-inf')
        for r in rectangles:
            x1 = min(x1, r[0]); y1 = min(y1, r[1])
            x2 = max(x2, r[2]); y2 = max(y2, r[3])
            area += (r[2]-r[0]) * (r[3]-r[1])
            for point in [(r[0],r[1]),(r[0],r[3]),(r[2],r[1]),(r[2],r[3])]:
                if point in corners:
                    corners.remove(point)
                else:
                    corners.add(point)
        if area != (x2-x1)*(y2-y1):
            return False
        return corners == {(x1,y1),(x1,y2),(x2,y1),(x2,y2)}

class Solution:
    def validUtf8(self, data: list[int]) -> bool:
        remaining = 0
        for byte in data:
            if remaining > 0:
                if byte >> 6 != 0b10:
                    return False
                remaining -= 1
            elif byte >> 7 == 0:
                remaining = 0
            elif byte >> 5 == 0b110:
                remaining = 1
            elif byte >> 4 == 0b1110:
                remaining = 2
            elif byte >> 3 == 0b11110:
                remaining = 3
            else:
                return False
        return remaining == 0

