class Solution:
    def minAbbreviation(self, target: str, dictionary: list[str]) -> str:
        n = len(target)
        diffs = []
        for word in dictionary:
            if len(word) != n:
                continue
            diff = 0
            for i in range(n):
                if target[i] != word[i]:
                    diff |= 1 << i
            diffs.append(diff)
        if not diffs:
            return str(n)
        def abbr_len(mask):
            length = 0
            i = 0
            while i < n:
                length += 1
                if mask & (1 << i):
                    i += 1
                else:
                    while i < n and not (mask & (1 << i)):
                        i += 1
            return length
        best = (1 << n) - 1
        for mask in range(1, 1 << n):
            if all(mask & d for d in diffs):
                if abbr_len(mask) < abbr_len(best):
                    best = mask
        res = []
        i = 0
        while i < n:
            if best & (1 << i):
                res.append(target[i])
                i += 1
            else:
                j = i
                while i < n and not (best & (1 << i)):
                    i += 1
                res.append(str(i - j))
        return ''.join(res)

