        res = []
        carry = 0
        i, j = len(num1)-1, len(num2)-1
        while i >= 0 or j >= 0 or carry:
            s = carry
            if i >= 0: s += int(num1[i]); i -= 1
            if j >= 0: s += int(num2[j]); j -= 1
            res.append(str(s % 10))
            carry = s // 10
        return ''.join(reversed(res))

class Solution:
    def pacificAtlantic(self, heights: list[list[int]]) -> list[list[int]]:
        if not heights:
            return []
        m, n = len(heights), len(heights[0])
        pacific = set()
        atlantic = set()
        def dfs(r, c, visited):
            visited.add((r, c))
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<m and 0<=nc<n and (nr,nc) not in visited and heights[nr][nc] >= heights[r][c]:
                    dfs(nr, nc, visited)
        for i in range(m):
            dfs(i, 0, pacific)
            dfs(i, n-1, atlantic)
        for j in range(n):
            dfs(0, j, pacific)
            dfs(m-1, j, atlantic)
        return [list(x) for x in pacific & atlantic]

