class Solution:
    def strongPasswordChecker(self, password: str) -> int:
        n = len(password)
        has_lower = any(c.islower() for c in password)
        has_upper = any(c.isupper() for c in password)
        has_digit = any(c.isdigit() for c in password)
        missing = (not has_lower) + (not has_upper) + (not has_digit)
        # Find repeating sequences
        repeats = []
        i = 2
        while i < n:
            if password[i] == password[i-1] == password[i-2]:
                j = i
                while j < n and password[j] == password[i-1]:
                    j += 1
                repeats.append(j - i + 2)
                i = j
            else:
                i += 1
        if n < 6:
            return max(missing, 6 - n)
        elif n <= 20:
            replace = sum(r // 3 for r in repeats)
            return max(missing, replace)
        else:
            delete = n - 20
            replace = sum(r // 3 for r in repeats)
            # Use deletions to reduce replacements
            remaining_delete = delete
            repeats.sort(key=lambda x: x % 3)
            for i in range(len(repeats)):
                if remaining_delete <= 0:
                    break
                need = repeats[i] % 3 + 1
                use = min(remaining_delete, need)
                repeats[i] -= use
                remaining_delete -= use
            for i in range(len(repeats)):
                if remaining_delete <= 0:
                    break
                use = min(remaining_delete, repeats[i] - 2)
                if use > 0:
                    repeats[i] -= use
                    remaining_delete -= use
            replace = sum(r // 3 for r in repeats)
            return delete + max(missing, replace)
